-- Migration 0056_ics: generated by drizzle-kit (tables, keys, indexes), RLS, the column-list SET NULL actions and the token resolver hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #53)
-- Calendar interoperability (#53; PRD CA-5; docs/product/09 §3, §8):
--   * ics_feed, ics_feed_event and ics_import_event: tenant tables (tenantTable()) under FORCE RLS
--     with ws_isolation (tenantPolicy()). Only the sha256 of a feed token is stored.
--   * The nullable composite FKs of ics_import_event (proposal, anchor, matter, proceeding) are
--     ON DELETE SET NULL (<column>) (Postgres 15+), like 0053: drizzle-kit writes a plain SET NULL,
--     which would also null the NOT NULL workspace_id; its snapshot keeps `set null`.
--   * app_ics_feed_resolve(token_hash) lets the unauthenticated feed route find the feed (and so
--     the workspace) behind a token before any workspace is set. SECURITY DEFINER, executable by
--     causedeck_app only, returns the feed's own columns for a non-revoked feed and nothing else;
--     owner_definer_read is the policy it needs.
-- Expand only: new tables, a policy and a function; no existing data is rewritten.
CREATE TABLE "ics_feed" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"token_hash" text NOT NULL,
	"scope" text DEFAULT 'mine' NOT NULL,
	"include_parties" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"rotated_at" timestamp with time zone,
	"last_fetched_at" timestamp with time zone,
	"revoked_at" timestamp with time zone,
	"disclosure_version" text NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "ics_feed_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "ics_feed_token_hash_uq" UNIQUE("token_hash"),
	CONSTRAINT "ics_feed_scope_chk" CHECK (scope in ('mine', 'workspace')),
	CONSTRAINT "ics_feed_token_hash_chk" CHECK (token_hash ~ '^[0-9a-f]{64}$')
);
--> statement-breakpoint
CREATE TABLE "ics_feed_event" (
	"feed_id" uuid NOT NULL,
	"uid" text NOT NULL,
	"sequence" integer DEFAULT 0 NOT NULL,
	"content_hash" text NOT NULL,
	"changed_at" timestamp with time zone NOT NULL,
	"cancelled_at" timestamp with time zone,
	"snapshot" jsonb NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "ics_feed_event_pkey" PRIMARY KEY("workspace_id","feed_id","uid"),
	CONSTRAINT "ics_feed_event_sequence_chk" CHECK (sequence >= 0)
);
--> statement-breakpoint
