CREATE FUNCTION app_ics_feed_resolve(p_token_hash text)
  RETURNS TABLE (workspace_id uuid, feed_id uuid, user_id uuid, token_hash text, scope text, include_parties boolean)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT f.workspace_id, f.id, f.user_id, f.token_hash, f.scope, f.include_parties FROM ics_feed f
    WHERE f.token_hash = p_token_hash AND f.revoked_at IS NULL
    LIMIT 1
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_ics_feed_resolve(text) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_ics_feed_resolve(text) TO causedeck_app;
